// One message per row of ideas_due() (D-083). Telegram text is Vietnamese (D-061); every value is
// escaped because the message is HTML. IDEAS rows get one button per idea (callback id:<token>,
// answered by WF-06 with the /new draft). The Send ideas node has 5 buttons: ideas_per_request()
// in SQL is 5 and idea_complete() stores exactly that many. FAILED / BLOCKED rows are notices.
// Daily requests have no chat: they go to the approval chat, filled in on deploy.
const APPROVAL_CHAT = 'REPLACE_WITH_APPROVAL_CHAT_ID';
const BUTTONS = 5;
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (value, max) => {
  const text = String(value ?? '').trim();
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
};
// Vietnam time (UTC+7, no daylight saving): "14:30 30/10".
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const parse = (value) => (typeof value === 'string' ? JSON.parse(value) : value);
const tag = (idea) => {
  if (idea.kind === 'series') return `🔗 Series: ${esc(idea.series_title)} · tập ${idea.episode_no}`;
  if (idea.kind === 'related') return `↪️ Liên quan: ${esc(idea.related_title ?? '')}`;
  return '✨ Mới';
};
return $input.all().map((item) => item.json).filter((row) => row.kind).map((row) => {
  const pair = `${esc(row.kit_label ?? row.kit)} · ${esc(row.character_label ?? row.character_set)}`;
  const chatId = row.chat_id ?? APPROVAL_CHAT;
  if (row.kind === 'FAILED') {
    return { json: { chatId, hasButtons: false, html: `⚠️ Không viết được ý tưởng cho ${pair}: ${esc(cut(row.error, 300))}\nGửi /ideas để thử lại.` } };
  }
  if (row.kind === 'BLOCKED') {
    const until = row.blocked_until ? ` (thử lại lúc ${vnTime(row.blocked_until)})` : '';
    return { json: { chatId, hasButtons: false, html: `⏸ Ý tưởng cho ${pair} đang chờ: Claude hết lượt dùng${until}.` } };
  }
  const ideas = parse(row.ideas) ?? [];
  const blocks = ideas.map((idea) => [
    `<b>${idea.position}. ${esc(cut(idea.topic, 300))}</b>`,
    tag(idea),
    `<i>${esc(cut(idea.hook, 150))}</i>`,
    esc(cut(idea.angle, 180)),
  ].join('\n'));
  const title = row.source === 'daily' ? '💡 Ý tưởng hôm nay' : '💡 Ý tưởng';
  const html = [
    `${title} · ${pair}`,
    ...blocks.flatMap((block) => ['', block]),
    '',
    'Bấm số để mở bản nháp /new (ý tưởng dùng được 7 ngày).',
  ].join('\n');
  const buttons = Object.fromEntries(
    Array.from({ length: BUTTONS }, (_, i) => [`idea${i + 1}`, ideas[i] ? `id:${ideas[i].token}` : '']),
  );
  return { json: { chatId, hasButtons: ideas.length === BUTTONS, html, ...buttons } };
});
